// Core1 spectrum reduction; all crossing bijections explicitly enumerated.
#include <bits/stdc++.h>
using namespace std;using E=vector<pair<int,int>>;using Sig=vector<uint64_t>;
struct ACase{E f;vector<int>ports;};struct DSU{int p[40];bool ok=true;DSU(){iota(p,p+40,0);}int root(int x){return p[x]==x?x:p[x]=root(p[x]);}void add(int a,int b){a=root(a);b=root(b);if(a==b)ok=false;else p[a]=b;}};
set<E>zeroFs;int c,nend,nr,words;int us[3]={3,5,9};vector<E> pats[3];vector<vector<int>> rp;vector<int> rm;unordered_map<uint64_t,int>ri;unordered_set<uint64_t> neg[3];array<int,16> fa,fb;E cur;map<Sig,vector<ACase>> atypes;vector<pair<Sig,vector<ACase>>> av;map<Sig,vector<int>> cache;long long na=0,nb=0,res=0,badB=0;ofstream out;
uint64_t rcode(vector<int>&m){uint64_t z=0;for(int i=0;i<(int)m.size();i++)z|=uint64_t(m[i])<<(4*i);return z;}
uint64_t mcode(array<int,16>&m){uint64_t z=0;for(int i=2;i<16;i++)if(m[i]>=0)z|=uint64_t(m[i])<<(4*i);return z;}
void genR(unsigned m){if(!m){ri[rcode(rm)]=rp.size();rp.push_back(rm);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int b=a+1;b<nend;b++)if(m>>b&1){rm[a]=b;rm[b]=a;genR(m^(1u<<b));}}
void genN(unsigned m,int f){if(!m){pats[f].push_back(cur);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int j=0;j<4;j++){int b=a^(1<<j);if(m>>b&1){cur.push_back({a,b});genN(m^(1u<<b),f);cur.pop_back();}}}
void assessA(){vector<int>ports;E F;for(int a=1;a<16;a++)if(a!=3&&a!=5&&a!=9){if(fa[a]<0)ports.push_back(a);else if(fa[a]>a)F.push_back({a,fa[a]});}Sig sig(words);for(int f=0;f<3;f++){vector<int>ep=ports;for(int z:us)if(z!=us[f])ep.push_back(z);for(auto&N:pats[f]){DSU d;for(auto[a,b]:F)d.add(a,b);for(auto[a,b]:N)d.add(a,b);if(!d.ok)continue;vector<int>m(nend,-1);for(int i=0;i<nend;i++)for(int j=0;j<nend;j++)if(i!=j&&d.root(ep[i])==d.root(ep[j])){assert(m[i]<0);m[i]=j;}assert(find(m.begin(),m.end(),-1)==m.end());int bit=f*nr+ri.at(rcode(m));sig[bit/64]|=1ull<<(bit%64);}}atypes[sig].push_back({F,ports});na++;}
void genA(unsigned m,int skip){if(!m){if(!skip)assessA();return;}int a=__builtin_ctz(m);m^=1u<<a;if(skip)genA(m,skip-1);for(int b=a+1;b<16;b++)if(m>>b&1){fa[a]=b;fa[b]=a;genA(m^(1u<<b),skip);fa[a]=fa[b]=-1;}}
void assessB(){vector<int>bp;E F;for(int a=2;a<16;a++)if(fb[a]<0)bp.push_back(a);else if(fb[a]>a)F.push_back({a,fb[a]});do{Sig sig(words);for(int f=0;f<3;f++){int s=-1,t=-1;for(int z:us)if(z!=us[f]){if(s<0)s=z;else t=z;}for(int k=0;k<nr;k++){DSU d;for(auto[a,b]:F)d.add(a,b);d.add(s,16+s);d.add(t,16+t);vector<int>ep=bp;ep.push_back(16+s);ep.push_back(16+t);for(int i=0;i<nend;i++)if(rp[k][i]>i)d.add(ep[i],ep[rp[k][i]]);if(!d.ok)continue;array<int,16>m;m.fill(-1);bool ok=true;for(int a=2;a<16;a++)if(a!=s&&a!=t){for(int b=2;b<16;b++)if(b!=a&&b!=s&&b!=t&&d.root(a)==d.root(b)){if(m[a]>=0)ok=false;m[a]=b;}if(m[a]<0)ok=false;}if(ok&&!neg[f].count(mcode(m))){int bit=f*nr+k;sig[bit/64]|=1ull<<(bit%64);}}}
 if(all_of(sig.begin(),sig.end(),[](uint64_t v){return !v;}))zeroFs.insert(F);auto it=cache.find(sig);if(it==cache.end()){vector<int>bad;for(int i=0;i<(int)av.size();i++){bool hit=false;for(int j=0;j<words;j++)if(sig[j]&av[i].first[j]){hit=true;break;}if(!hit)bad.push_back(i);}it=cache.emplace(sig,bad).first;}nb++;if(!it->second.empty())badB++;for(int idx:it->second){if(c>0){res+=av[idx].second.size();continue;}for(auto&a:av[idx].second){res++;for(auto[x,y]:a.f){out.put(char(2*x+1));out.put(char(2*y+1));}for(auto[x,y]:F){out.put(char(2*x));out.put(char(2*y));}for(int j=0;j<c;j++){out.put(char(2*a.ports[j]+1));out.put(char(2*bp[j]));}}}}while(next_permutation(bp.begin(),bp.end()));}
void genB(unsigned m,int skip){if(!m){if(!skip)assessB();return;}int a=__builtin_ctz(m);m^=1u<<a;if(skip)genB(m,skip-1);for(int b=a+1;b<16;b++)if(m>>b&1){fb[a]=b;fb[b]=a;genB(m^(1u<<b),skip);fb[a]=fb[b]=-1;}}
int main(int argc,char**argv){if(argc!=2)return 2;c=stoi(argv[1]);nend=c+2;rm.resize(nend);genR((1u<<nend)-1);nr=rp.size();words=(3*nr+63)/64;ifstream ni("t15_core1_route_negative.txt");int f;while(ni>>f){array<int,16>m;m.fill(-1);for(int j=0;j<6;j++){int a,b;ni>>a>>b;m[a]=b;m[b]=a;}neg[f].insert(mcode(m));}for(int f=0;f<3;f++){int u=us[f];for(int i=0;i<4;i++)for(int j=i+1;j<4;j++){int a=u^(1<<i),b=u^(1<<j);if(!a||!b)continue;cur={{u,a},{u,b}};genN(65534u&~(1u<<u)&~(1u<<a)&~(1u<<b),f);}}fa.fill(-1);fb.fill(-1);genA(65534u&~(1u<<3)&~(1u<<5)&~(1u<<9),c);for(auto&z:atypes)av.push_back(z);cerr<<"c"<<c<<" A"<<na<<" types"<<av.size()<<" patterns"<<pats[0].size()<<","<<pats[1].size()<<","<<pats[2].size()<<"\n";if(!c)out.open("t15_core1_route_c0_residual_inputs.bin",ios::binary);if(c<4)genB(65532u,c);else{ifstream in("t15_core1_route_B"+to_string(c)+".txt");int a,b;while(in>>a>>b){fb.fill(-1);fb[a]=b;fb[b]=a;for(int j=1;j<(14-c)/2;j++){in>>a>>b;fb[a]=b;fb[b]=a;}assessB();}}ofstream bz("t15_core1_route_zero_B"+to_string(c)+".txt");for(auto&F:zeroFs){for(auto[x,y]:F)bz<<x<<" "<<y<<" ";bz<<"\n";}cout<<"{\"c\":"<<c<<",\"A_count\":"<<na<<",\"A_types\":"<<av.size()<<",\"B_ordered_count\":"<<nb<<",\"B_types\":"<<cache.size()<<",\"bad_ordered_B\":"<<badB<<",\"residual_inputs\":"<<res<<"}\n";}
